// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 extraAmount) public {
        vm.assume(depositAmount <= 1e20);
        vm.assume(extraAmount <= 1e20);
        vm.assume(depositAmount > 0);
        address sender = address(this);
        vm.deal(sender, depositAmount + extraAmount);
        // fund the contract using fallback so depositsCount increases (not required for property but harmless)
        vm.prank(sender);
        (bool ok, ) = address(c).call{value: depositAmount}("");
        require(ok, "fallback deposit failed");
        // optionally send more ether to have a non-zero balance before withdrawAll
        if (extraAmount > 0) {
            vm.prank(sender);
            (ok, ) = address(c).call{value: extraAmount}("");
            require(ok, "second deposit failed");
        }
        uint256 balanceBefore = address(c).balance;
        assertTrue(balanceBefore > 0, "contract must have balance");
        // owner calls withdrawAll (sender is the owner because setUp called new C() in this test context)
        c.withdrawAll();
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter == 0, "withdrawAll must zero the contract balance");
    }
}

