        // 1. restrict to sensible deposit amount
        vm.assume(_amount > 0);
        vm.assume(_amount <= address(c).balance + 1e30); // keep wide
        // 2. fund the contract via a deposit from some address
        address depositor = address(0xdead);
        vm.deal(depositor, _amount);
        vm.prank(depositor);
        (bool ok,) = address(c).call{value: _amount}("");
        require(ok, "deposit failed");
        uint256 balanceBefore = address(c).balance;
        // owner calls withdrawAll
        vm.prank(c.owner());
        c.withdrawAll();
        uint256 balanceAfter = address(c).balance;
        // balanceAfter must be 0 in reference; bug keeps it unchanged
        assertTrue(balanceAfter == 0);
    }
}

