contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialBalance, uint256 withdrawAmount) public {
        // Restrict to admissible domain: balance must be > 0 to observe a change
        bound(initialBalance, 1, address(this).balance);
        vm.assume(initialBalance > 0);
        // Deal some ETH to the contract
