pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, uint256 ownerInitBalance) public {
        // Bound amounts to avoid overflow and ensure sufficient balance
        depositAmount = bound(depositAmount, 1, 100 ether);
        withdrawAmount = bound(withdrawAmount, 0, 100 ether);
        ownerInitBalance = bound(ownerInitBalance, 0, 1000 ether);
        vm.deal(address(c).owner, ownerInitBalance);

        // Set up contract with deposit via fallback
        vm.deal(address(this), depositAmount);
        vm.prank(address(this));
        (bool sent,) = address(c).call{value: depositAmount}("");
        require(sent, "fallback deposit failed");

        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Owner calls withdrawAll
        vm.prank(address(c).owner);
        try c.withdrawAll() { } catch { }

        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // Invariant: balance never increases after withdrawAll, and if balance was non-zero before,
        // depositsCount remains unchanged (no new fallback triggered within withdrawAll itself).
        // Mutant withdraws 0, so balance stays same; but owner could have also separately triggered fallback,
        // however the invariant focuses on withdrawAll: it must not increase balance and must not alter depositsCount
        // except through a payable receiver? Actually withdrawAll only calls withdraw(0) which does nothing,
        // so depositsCount should stay exactly the same. In reference, withdrawAll sends all balance out,
        // balance becomes 0, depositsCount unchanged. Mutant leaves balance unchanged, depositsCount unchanged.
        // To catch the bug, we assert that if beforeBalance > 0, then afterBalance < beforeBalance.
        // This holds for reference (balance goes to 0), fails for mutant (balance stays).
        assertTrue(beforeBalance == 0 || afterBalance < beforeBalance);
    }
}

