pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 extraDeposit) public {
        address owner = c.owner();
        vm.assume(owner != address(0));
        vm.assume(depositAmount < type(uint256).max);
        vm.assume(extraDeposit < type(uint256).max);
        vm.assume(depositAmount + extraDeposit <= address(this).balance);
        vm.assume(depositAmount + extraDeposit >= depositAmount);

        // Deposit funds into the contract
        vm.deal(address(this), depositAmount + extraDeposit);
        (bool sent1,) = address(c).call{value: depositAmount}("");
        require(sent1);
        (bool sent2,) = address(c).call{value: extraDeposit}("");
        require(sent2);

        uint256 balanceBefore = address(c).balance;
        uint256 ownerBalanceBefore = owner.balance;

        vm.prank(owner);
        c.withdrawAll();

        uint256 ownerBalanceAfter = owner.balance;
        uint256 ownerDelta = ownerBalanceAfter - ownerBalanceBefore;

        assertTrue(ownerDelta == balanceBefore);
    }
}

