pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // bound deposit amount to avoid overflow and ensure non-trivial balance
        depositAmount = bound(depositAmount, 1, 1000 ether);
        withdrawAmount = bound(withdrawAmount, 0, depositAmount);
        vm.assume(depositAmount > 0);

        // fund the owner
        address owner = c.owner();
        vm.deal(owner, depositAmount);

        // owner deposits Ether via fallback
        vm.prank(owner);
        (bool ok,) = address(c).call{value: depositAmount}("");
        require(ok, "deposit failed");

        uint256 contractBalBefore = address(c).balance;
        vm.prank(owner);
        c.withdrawAll();
        uint256 contractBalAfter = address(c).balance;

        // With a single deposit and a subsequent withdrawAll, the reference
        // contract must drain its entire balance, leaving 0.
        // The buggy version withdraws only 1 wei, leaving a non-zero balance.
        assertTrue(contractBalAfter == 0);
    }
}

