contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes calldata data) public {
        vm.assume(target != address(0));
        vm.assume(target != address(c));
        vm.assume(value > 0);
        vm.assume(value <= address(this).balance);
        vm.deal(address(c), value);
        uint256 beforeBal = address(c).balance;
        vm.prank(c.owner());
        (bool ok, ) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", target, value, data));
        vm.assume(ok);
        uint256 afterBal = address(c).balance;
        assertEq(afterBal, beforeBal - value);
    }
}

