pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        vm.deal(address(this), 100 ether);
        c = new C();
        vm.deal(address(c), 10 ether);
    }
    function testFuzz_property(address target, uint256 value, bytes calldata data) public {
        vm.assume(target != address(c));
        vm.assume(target != c.owner());
        value = bound(value, 1, address(c).balance);

        address owner = c.owner();
        uint256 ownerBalanceBefore = owner.balance;
        uint256 contractBalanceBefore = address(c).balance;

        vm.prank(owner);
        c.sendMoney(target, value, data);

        uint256 ownerBalanceAfter = owner.balance;
        uint256 contractBalanceAfter = address(c).balance;

        assertTrue(ownerBalanceBefore + contractBalanceBefore == ownerBalanceAfter + contractBalanceAfter);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _target, uint _value, bytes memory _data, address _sender) public payable {
        require(true);
        bool reverted; try c.sendMoney(_target, _value, _data) { reverted = false; } catch { reverted = true; }
        assert(!reverted ? _sender == c.owner() : true);
    }
}

