pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint256 amount, bytes calldata data) public {
        // sender must be different from owner so the non-owner path can be exercised
        vm.assume(sender != address(0));
        vm.assume(sender != c.owner());
        // amount must be > 0 to observe a balance change
        vm.assume(amount > 0);
        // Ensure the contract has enough balance to cover the send (owner will fund it)
        // Owner deposits the amount plus some extra to avoid balance underflow issues
        vm.deal(c.owner(), amount);
        vm.prank(c.owner());
        (bool ok,) = address(c).call{value: amount}("");
        require(ok);
        uint256 balanceBefore = address(c).balance;
        // Non-owner attempts to send the full amount
        vm.prank(sender);
        (bool sentOk,) = address(c).call{value: 0}(
            abi.encodeWithSelector(C.sendMoney.selector, sender, amount, data)
        );
        // Rule: A non-owner call to sendMoney must NOT succeed (must revert).
        // The reference contract always reverts because onlyOwner is enforced.
        // The buggy contract can succeed, moving funds without owner consent.
        assertFalse(sentOk, "non-owner sendMoney should revert");
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address target, uint value, bytes memory data) public payable {
        require(true);
        bool reverted;
        try c.sendMoney(target, value, data) { reverted = false; } catch { reverted = true; }
        assert((msg.sender != c.owner()) ? reverted : true);
    }
}

